package com.example.json;

public class Person {

    private String name;
    private int age;
    private String email;

    public Person() {
    }

    public Person(String name, int age, String email) {
        this.name = name;
        this.age = age;
        this.email = email;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public int getAge() {
        return age;
    }

    public void setAge(int age) {
        this.age = age;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    @Override
    public String toString() {
        return "Person{name='" + name + "', age=" + age + ", email='" + email + "'}";
    }
}

package com.example.json;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

public final class JsonDemo {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private JsonDemo() {
    }

    public static void main(String[] args) throws Exception {
        Person person = new Person("Ada Lovelace", 36, "ada@example.com");

        String json = toJson(person);
        System.out.println("Generated JSON: " + json);
        System.out.println("Pretty JSON:\n" + toPrettyJson(person));

        Person parsed = fromJson(json, Person.class);
        System.out.println("Parsed object:  " + parsed);

        JsonNode tree = parseTree(json);
        System.out.println("Tree name:      " + tree.get("name").asText());
    }

    public static String toJson(Object value) throws Exception {
        return MAPPER.writeValueAsString(value);
    }

    public static String toPrettyJson(Object value) throws Exception {
        return MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(value);
    }

    public static <T> T fromJson(String json, Class<T> type) throws Exception {
        return MAPPER.readValue(json, type);
    }

    public static JsonNode parseTree(String json) throws Exception {
        return MAPPER.readTree(json);
    }

    public static String toJsonWithExtraField(Person person, String key, String value) throws Exception {
        ObjectNode node = MAPPER.valueToTree(person);
        node.put(key, value);
        return toJson(node);
    }
}

package com.example.json;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class JsonDemoTest {

    @Test
    void generatesAndParsesRoundTrip() throws Exception {
        Person person = new Person("Ada Lovelace", 36, "ada@example.com");

        String json = JsonDemo.toJson(person);
        Person parsed = JsonDemo.fromJson(json, Person.class);

        assertEquals(person.getName(), parsed.getName());
        assertEquals(person.getAge(), parsed.getAge());
        assertEquals(person.getEmail(), parsed.getEmail());
    }

    @Test
    void parsesTree() throws Exception {
        var tree = JsonDemo.parseTree("{\"name\":\"Grace\",\"age\":45}");

        assertEquals("Grace", tree.get("name").asText());
        assertEquals(45, tree.get("age").asInt());
    }

    @Test
    void addsExtraField() throws Exception {
        String json = JsonDemo.toJsonWithExtraField(new Person("Alan", 41, "alan@example.com"), "role", "admin");

        assertEquals("admin", JsonDemo.parseTree(json).get("role").asText());
    }
}
